WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT island_id, DATE_TRUNC('DAY', reading_ts) AS activity_day, ROUND(AVG(island_id), 2) AS avg_island_id, ROUND(SUM(humidity) / NULLIF(COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END), 0), 2) AS humidity_per_dv_01, SIZE(COLLECT_SET(device_code)) AS num_device_codes, APPROX_PERCENTILE(island_id, 0.95) AS island_id_p95, BIT_AND(status_bits) AS status_bits_bit_and, COUNT_IF(device_code = 'DV-02') AS dv_02_events, GROUPING(island_id) AS gid FROM islands GROUP BY GROUPING SETS ((island_id, DATE_TRUNC('DAY', reading_ts)), (island_id)) HAVING COUNT_IF(device_code = 'DV-02') >= 1;
